from pathlib import Path
from playwright.sync_api import sync_playwright
import json,hashlib,os
R=Path(os.environ.get('OCEAN_R03_REPLAY_DIR',str(Path(__file__).resolve().parents[3]/'r03-study')));kernel=(R/'src/field-kernel.js').read_text();data=(R/'FISH_REF001_FIELD_COMPACT.json').read_text()
js=r'''const gl=document.querySelector('canvas').getContext('webgl2',{preserveDrawingBuffer:true});if(!gl)throw Error('WebGL2 missing');
function shader(t,s){const a=gl.createShader(t);gl.shaderSource(a,s);gl.compileShader(a);if(!gl.getShaderParameter(a,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(a));return a;}
const p=gl.createProgram();gl.attachShader(p,shader(gl.VERTEX_SHADER,`#version 300 es
precision highp float;in vec3 pos,n,col,par;uniform float aspect,zoom,angle,width;out vec3 c,N;out float alpha,rough;void main(){float x=pos.z*cos(angle)+pos.x*sin(angle),z=pos.x*cos(angle)-pos.z*sin(angle);gl_Position=vec4(x*zoom,pos.y*zoom*aspect,-z*.5,1.);gl_PointSize=clamp(par.z*width*zoom,1.2,24.);c=col;N=n;alpha=par.x;rough=par.y;}`));
gl.attachShader(p,shader(gl.FRAGMENT_SHADER,`#version 300 es
precision highp float;in vec3 c,N;in float alpha,rough;uniform int passId;out vec4 o;void main(){if(length(gl_PointCoord-.5)>.5||alpha<.01)discard;if(passId==0&&alpha<.995)discard;if(passId==1&&alpha>=.995)discard;float l=.5+.5*abs(dot(normalize(N),normalize(vec3(.7,.5,.4))));vec3 a=pow(clamp(c*l,0.,1.),vec3(1./2.2));o=vec4(a,passId==0?1.:alpha);}`));
gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(p));gl.useProgram(p);const buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);for(const [name,offset]of[['pos',0],['n',3],['col',6],['par',9]]){let a=gl.getAttribLocation(p,name);gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,3,gl.FLOAT,false,72,offset*4);}
const d=FieldKernel.decode(FIELD);const cache={};let current=null,angle=.1;
window.renderStudy=(pixels)=>{const t=performance.now();current=cache[pixels]||(cache[pixels]=FieldKernel.fish(d,FieldKernel.conduct(pixels)));const cv=gl.canvas;cv.width=innerWidth;cv.height=innerHeight-Math.ceil(document.querySelector('header').getBoundingClientRect().height);gl.viewport(0,0,cv.width,cv.height);gl.clearColor(.035,.05,.06,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.enable(gl.DEPTH_TEST);gl.depthMask(true);gl.disable(gl.BLEND);gl.bufferData(gl.ARRAY_BUFFER,current.data,gl.STATIC_DRAW);gl.uniform1f(gl.getUniformLocation(p,'aspect'),cv.width/cv.height);gl.uniform1f(gl.getUniformLocation(p,'zoom'),Math.min(1.65,1.6*cv.height/cv.width));gl.uniform1f(gl.getUniformLocation(p,'angle'),angle);gl.uniform1f(gl.getUniformLocation(p,'width'),cv.width);gl.uniform1i(gl.getUniformLocation(p,'passId'),0);gl.drawArrays(gl.POINTS,0,current.count);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.depthMask(false);gl.uniform1i(gl.getUniformLocation(p,'passId'),1);gl.drawArrays(gl.POINTS,0,current.count);gl.depthMask(true);gl.finish();const b=new Uint8Array(cv.width*cv.height*4);gl.readPixels(0,0,cv.width,cv.height,gl.RGBA,gl.UNSIGNED_BYTE,b);let changed=0;for(let i=0;i<b.length;i+=4)if(b[i]>35||b[i+1]>35||b[i+2]>35)changed++;document.getElementById('state').textContent=`${pixels}px field plan / ${current.count} points / source-replay inspection`;return{pixels,count:current.count,ms:performance.now()-t,finite:current.data.every(Number.isFinite),glError:gl.getError(),foregroundPixels:changed,triangles:current.sourceTriangleCount};};window.rotateStudy=()=>{angle+=.6;return renderStudy(420)};document.getElementById('near').onclick=()=>renderStudy(420);document.getElementById('far').onclick=()=>renderStudy(15);document.getElementById('rotate').onclick=()=>rotateStudy();renderStudy(420);window.ready=true;'''
h='<!doctype html><html><meta charset="utf-8"><style>body{margin:0;background:#0a1014;color:#ccc;font:13px sans-serif}header{min-height:54px;padding:4px;box-sizing:border-box}canvas{display:block}button{margin:2px}</style><header><button id="near">Near</button><button id="far">Far</button><button id="rotate">Rotate</button><span id="state"></span><br>REAL SOURCE COEFFICIENT REPLAY / INTERNAL QA, NOT FINAL WORKBENCH</header><canvas></canvas><script>const FIELD='+data+';'+kernel+'\n'+js+'</script></html>'
(R/'SOURCE_REPLAY_INTERNAL.html').write_text(h)
report={'scope':'actual regenerated black-bass coefficient payload and pinned current kernel in Chromium; minimal inspection renderer, NOT full production study runtime, NOT public navigation','htmlSha256':hashlib.sha256(h.encode()).hexdigest(),'viewports':[]}
with sync_playwright()as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader','--disable-dev-shm-usage'])
 for W,H in [(1280,900),(390,844)]:
  page=browser.new_page(viewport={'width':W,'height':H});errs=[];page.on('pageerror',lambda e:errs.append(str(e)));page.set_content(h,wait_until='load');page.wait_for_function('window.ready',timeout=60000)
  states=[page.evaluate('(n)=>renderStudy(n)',px)for px in [15,100,420]];page.screenshot(path=str(R/f'qa/bass-restored-{W}.png'));page.locator('#far').click();state=page.evaluate('document.getElementById("state").textContent');page.locator('#near').click();page.locator('#rotate').click();page.screenshot(path=str(R/f'qa/bass-rotated-{W}.png'))
  report['viewports'].append({'size':[W,H],'states':states,'errors':errs,'farButtonState':state,'horizontalOverflow':page.evaluate('document.documentElement.scrollWidth>innerWidth')});page.close()
 browser.close()
report['pass']=all(not v['errors']and not v['horizontalOverflow']and all(s['finite']and s['glError']==0 and s['foregroundPixels']>0 for s in v['states'])for v in report['viewports']);report['visualAcceptance']=False;report['shareAllowed']=False
(R/'qa/BROWSER_REAL_SOURCE.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2));assert report['pass']
